gdjs._36938_25138Code.userFunc0x1187948 = function GDJSInlineCode(runtimeScene) {
"use strict";
 // ==========================================
 // CHAIN / MATCH
 // 全場景 UI HOVER 音效 V2
 //
 // 滑鼠移入按鈕：播放一次
 // 停留按鈕：不重複
 // 離開後再次移入：重新播放
 // ==========================================

 const SOUND = "UI_Hover.mp3";
 
const VOLUME = Math.max(0, Math.min(100,
  runtimeScene.getGame()
    .getVariables()
    .get("SFXVolume")
    .getAsNumber()
));
  

 // 沒有以 Button 結尾的按鈕，
 // 可以將名稱加入這裡。
 const EXTRA_BUTTONS = [
   "PauseHome",
   "PauseRestart",
   "Skill1Button",
   "Skill2Button",
   "Skill3Button",
   "START", 
   "Setting",
   "BACK",
   "SelectLeft",
   "SelectLight",
   "TimedButton",
   "FreeButton",
   "ConfirmButton",
   "retry",
   "MENU",
   "NewButton"
 ];

 // 記住上一次滑鼠停在哪顆按鈕
 if (runtimeScene._uiHoverLast === undefined) {
   runtimeScene._uiHoverLast = null;
 }

 // 遊戲是否正在暫停
 const isGame = runtimeScene.getName() === "遊戲";

 const isPaused = isGame &&
   runtimeScene.getVariables()
     .get("PauseOpen")
     .getAsNumber() === 1;

 // 暫停選單中的按鈕
 const pauseButtons = [
   "PauseButton2",
   "PauseHome",
   "PauseRestart"
 ];

 // 取得圖層順序
 const layers = [];
 runtimeScene.getAllLayerNames(layers);

 let hovered = null;
 let highest = -Infinity;

 // 搜尋目前場景中的按鈕
 const objects =
   runtimeScene.getAdhocListOfAllInstances();

 for (const obj of objects) {

   const name = obj.getName();

   // 自動辨識 Button / Button2 等名稱
   const isButton =
     /Button\d*$/i.test(name) ||
     EXTRA_BUTTONS.includes(name);

   if (!isButton) continue;

   // 忽略隱藏的按鈕
   if (!obj.isVisible()) continue;

   const layer = runtimeScene.getLayer(
     obj.getLayer()
   );

   if (!layer.isVisible()) continue;

   // 暫停時不偵測底下的遊戲按鈕
   if (isGame) {

     const isPauseMenu =
       pauseButtons.includes(name);

     if (isPaused && !isPauseMenu) {
       continue;
     }

     if (!isPaused && isPauseMenu) {
       continue;
     }
   }

   // 滑鼠不在按鈕上就跳過
   if (!obj.cursorOnObject()) continue;

   // 按鈕重疊時，選最上面的
   const layerIndex =
     layers.indexOf(obj.getLayer());

   const order =
     layerIndex * 100000 + obj.getZOrder();

   if (order > highest) {
     highest = order;
     hovered = obj;
   }
 }

 // 游標進入另一顆按鈕時才播聲音
 if (hovered !== runtimeScene._uiHoverLast) {

   if (hovered) {

     gdjs.evtTools.sound.playSound(
       runtimeScene,
       SOUND,
       false,
       VOLUME,
       1
     );
   }

   // 記住目前按鈕，沒有則記 null
   runtimeScene._uiHoverLast = hovered;
 }

};
gdjs._36938_25138Code.userFunc0x159e0c0 = function GDJSInlineCode(runtimeScene) {
"use strict";
 // ==========================================
 // CHAIN / MATCH
 // ScreenFX V9 - CCTV + DEPTH RGB
 //
 // 1. CRT 曲面
 // 2. 大範圍暈影
 // 3. 水平掃描線
 // 4. 少量動態雜訊
 // 5. 移動訊號線
 // 6. 遠近漸變 RGB 色差
 //
 // 不需要額外素材
 // ==========================================


 // ==========================================
 // 1. 效果設定
 // ==========================================

 // ===== CCTV =====

 const SCANLINE = 0.10;
 const NOISE = 0.015;

 const CURVATURE = 0.035;

 const VIGNETTE = 0.45;
 const VIGNETTE_START = 0.35;
 const VIGNETTE_END = 1.20;

 const ROLLING_LINE = 0.018;
 const ROLL_SPEED = 0.06;

 const LINE_SPACING = 4.0;


 // ===== RGB 遠近色差 =====

 // 畫面中央色差（像素）
 const RGB_NEAR = 0.2;

 // 畫面四周色差（像素）
 const RGB_FAR = 3.5;

 // 色差呼吸強度
 // 0 = 不呼吸
 const RGB_BREATH = 0.12;

 // 色差呼吸速度
 const RGB_SPEED = 0.65;


 // ==========================================
 // 2. 取得 PixiJS
 // ==========================================

 if (
   typeof PIXI !== "undefined" &&
   PIXI.Filter
 ) {

   const container =
     runtimeScene.getRenderer()
       .getPIXIContainer();

   const width = Math.max(
     1,
     runtimeScene.getViewportWidth()
   );

   const height = Math.max(
     1,
     runtimeScene.getViewportHeight()
   );

   let fx = runtimeScene._chainScreenFX;


   // ========================================
   // 3. 初始化濾鏡
   // ========================================

   if (
     !fx ||
     fx.version !== 9 ||
     fx.container !== container
   ) {

     // 移除舊版 ScreenFX
     if (
       fx &&
       fx.filter &&
       fx.container
     ) {

       fx.container.filters =
         (fx.container.filters || [])
           .filter(f => f !== fx.filter);
     }


     // ======================================
     // 4. CCTV + RGB Shader
     // ======================================

     const fragment = `
       precision mediump float;

       varying vec2 vTextureCoord;

       uniform sampler2D uSampler;
       uniform vec4 inputClamp;

       uniform vec2 uScreenSize;

       uniform float uTime;

       uniform float uScanline;
       uniform float uNoise;
       uniform float uCurve;
       uniform float uVignette;

       uniform float uVignetteStart;
       uniform float uVignetteEnd;

       uniform float uRolling;
       uniform float uRollSpeed;
       uniform float uLineSpacing;

       // RGB 色差
       uniform float uRGBNear;
       uniform float uRGBFar;
       uniform float uRGBBreath;
       uniform float uRGBSpeed;


       // ================================
       // 隨機雜訊函式
       // ================================

       float hash(vec2 p) {

         return fract(
           sin(dot(
             p,
             vec2(127.1, 311.7)
           )) * 43758.5453
         );
       }


       void main(void) {

         // ================================
         // A. 畫面座標
         // ================================

         vec2 range = max(
           inputClamp.zw - inputClamp.xy,
           vec2(0.0001)
         );

         vec2 uv =
           (vTextureCoord - inputClamp.xy)
           / range;

         vec2 centered =
           uv * 2.0 - 1.0;


         // ================================
         // B. CRT 曲面
         // ================================

         float radius =
           dot(centered, centered);

         vec2 bent =
           centered *
           (1.0 + uCurve * radius);

         vec2 curvedUV =
           bent * 0.5 + 0.5;


         // ================================
         // C. 曲面邊緣
         // ================================

         float edgeDistance = min(
           min(
             curvedUV.x,
             1.0 - curvedUV.x
           ),
           min(
             curvedUV.y,
             1.0 - curvedUV.y
           )
         );

         float edgeMask =
           smoothstep(
             -0.005,
             0.016,
             edgeDistance
           );


         // ================================
         // D. RGB 遠近計算
         // ================================

         // 計算離畫面中心的距離
         float distanceFromCenter =
           length(
             centered *
             vec2(1.0, 0.92)
           );

         // 0 = 中央
         // 1 = 四周
         float depth =
           smoothstep(
             0.12,
             1.20,
             distanceFromCenter
           );

         // 中央色差弱
         // 越靠近四周色差越強
         float rgbStrength =
           mix(
             uRGBNear,
             uRGBFar,
             depth
           );

         // 非常緩慢的呼吸變化
         float breathing =
           1.0 +
           sin(uTime * uRGBSpeed)
           * uRGBBreath;

         rgbStrength *= breathing;


         // ================================
         // E. RGB 分離方向
         // ================================

         // 讓色差沿著中心向外擴散
         vec2 direction =
           centered /
           max(length(centered), 0.0001);

         // 將像素位移換成 UV 位移
         vec2 rgbOffset =
           direction *
           rgbStrength /
           max(uScreenSize, vec2(1.0));

         // 紅色向外
         vec2 redUV =
           curvedUV + rgbOffset;

         // 藍色向內
         vec2 blueUV =
           curvedUV - rgbOffset;

         // 分別限制在畫面範圍內
         vec2 normalUV =
           clamp(curvedUV, 0.0, 1.0);

         redUV =
           clamp(redUV, 0.0, 1.0);

         blueUV =
           clamp(blueUV, 0.0, 1.0);


         // ================================
         // F. 讀取 RGB 三個通道
         // ================================

         vec2 normalSample = mix(
           inputClamp.xy,
           inputClamp.zw,
           normalUV
         );

         vec2 redSample = mix(
           inputClamp.xy,
           inputClamp.zw,
           redUV
         );

         vec2 blueSample = mix(
           inputClamp.xy,
           inputClamp.zw,
           blueUV
         );

         vec4 original = texture2D(
           uSampler,
           normalSample
         );

         vec4 redPart = texture2D(
           uSampler,
           redSample
         );

         vec4 bluePart = texture2D(
           uSampler,
           blueSample
         );

         // 合成三個顏色通道
         vec3 color = vec3(
           redPart.r,
           original.g,
           bluePart.b
         );


         // ================================
         // G. CCTV 水平掃描線
         // ================================

         float pixelY =
           uv.y * uScreenSize.y;

         float scan =
           0.5 +
           0.5 * cos(
             pixelY *
             6.2831853 /
             max(uLineSpacing, 1.0)
           );

         color *=
           1.0 - scan * uScanline;


         // ================================
         // H. 少量動態雜訊
         // ================================

         vec2 noiseCell =
           floor(
             uv * uScreenSize / 3.0
           );

         float frame =
           floor(uTime * 16.0);

         float randomNoise =
           hash(
             noiseCell +
             vec2(
               frame * 1.7,
               frame * 2.3
             )
           ) - 0.5;

         color += vec3(
           randomNoise *
           uNoise *
           original.a
         );


         // ================================
         // I. 緩慢移動的訊號線
         // ================================

         float rollY =
           fract(uTime * uRollSpeed);

         float rollingBand =
           exp(
             -abs(uv.y - rollY) * 90.0
           );

         color *=
           1.0 -
           rollingBand * uRolling;


         // ================================
         // J. 大範圍暈影
         // ================================

         float vignette =
           smoothstep(
             uVignetteStart,
             uVignetteEnd,
             distanceFromCenter
           );

         color *=
           1.0 -
           vignette * uVignette;


         // ================================
         // K. CRT 曲面黑邊
         // ================================

         color *= edgeMask;

         float alpha = mix(
           1.0,
           original.a,
           edgeMask
         );


         // ================================
         // L. 輸出畫面
         // ================================

         gl_FragColor = vec4(
           clamp(color, 0.0, 1.0),
           clamp(alpha, 0.0, 1.0)
         );

       }
     `;


     // ======================================
     // 5. 建立 PixiJS Filter
     // ======================================

     const filter = new PIXI.Filter(
       undefined,
       fragment,
       {

         uScreenSize: [
           width,
           height
         ],

         uTime: 0,

         // CCTV
         uScanline: SCANLINE,
         uNoise: NOISE,

         uCurve: CURVATURE,
         uVignette: VIGNETTE,

         uVignetteStart:
           VIGNETTE_START,

         uVignetteEnd:
           VIGNETTE_END,

         uRolling: ROLLING_LINE,
         uRollSpeed: ROLL_SPEED,

         uLineSpacing: LINE_SPACING,

         // RGB 遠近
         uRGBNear: RGB_NEAR,
         uRGBFar: RGB_FAR,
         uRGBBreath: RGB_BREATH,
         uRGBSpeed: RGB_SPEED

       }
     );


     // 保留其他已存在的濾鏡
     container.filters = [
       ...(container.filters || []),
       filter
     ];


     // 套用到整個畫面
     container.filterArea =
       new PIXI.Rectangle(
         0,
         0,
         width,
         height
       );


     // ======================================
     // 6. 儲存特效狀態
     // ======================================

     fx = {

       version: 9,

       container,
       filter,

       time: 0

     };

     runtimeScene._chainScreenFX = fx;

   }


   // ========================================
   // 7. 每幀更新
   // ========================================

   const dt = Math.max(
     0,
     Math.min(
       runtimeScene.getElapsedTime() / 1000,
       0.05
     )
   );

   fx.time += dt;


   // ========================================
   // 8. 更新 CCTV 參數
   // ========================================

   const uniforms =
     fx.filter.uniforms;

   uniforms.uTime =
     fx.time;

   uniforms.uScanline =
     SCANLINE;

   uniforms.uNoise =
     NOISE;

   uniforms.uCurve =
     CURVATURE;

   uniforms.uVignette =
     VIGNETTE;

   uniforms.uVignetteStart =
     VIGNETTE_START;

   uniforms.uVignetteEnd =
     VIGNETTE_END;

   uniforms.uRolling =
     ROLLING_LINE;

   uniforms.uRollSpeed =
     ROLL_SPEED;

   uniforms.uLineSpacing =
     LINE_SPACING;


   // ========================================
   // 9. 更新 RGB 遠近參數
   // ========================================

   uniforms.uRGBNear =
     RGB_NEAR;

   uniforms.uRGBFar =
     RGB_FAR;

   uniforms.uRGBBreath =
     RGB_BREATH;

   uniforms.uRGBSpeed =
     RGB_SPEED;


   // ========================================
   // 10. 更新畫面尺寸
   // ========================================

   uniforms.uScreenSize = [
     width,
     height
   ];

   fx.container.filterArea.width =
     width;

   fx.container.filterArea.height =
     height;

 }

};
gdjs._36938_25138Code.userFunc0xda0ca8 = function GDJSInlineCode(runtimeScene) {
"use strict";

 // ==========================================
 // CHAIN / MATCH
 // GRID DISTORTION V1
 //
 // 網格呼吸 / 柔和波紋變形
 //
 // 不需要 Sprite
 // 不使用 Shader / BlurFilter
 // 不影響遊戲操作及技能
 // ==========================================


 // ==========================================
 // 1. 可以自由修改的設定
 // ==========================================

 // 專用圖層
 const GRID_LAYER = "GridBreath";

 // 網格間距：越小越密集
 const GRID_SPACING = 100;

 // 線條寬度
 const LINE_WIDTH = 4;

 // 線條顏色：灰色
 const LINE_COLOR = 0x3cff2a;

 // 透明度：0 ~ 1
 const LINE_ALPHA = 0.22;

 // 變形幅度：越大越有波浪感
 const DISTORT_STRENGTH = 24;

 // 呼吸幅度
 const BREATH_STRENGTH = 12;

 // 動畫速度
 const WAVE_SPEED = 0.75;

 // 呼吸速度
 const BREATH_SPEED = 0.55;

 // 波紋密度
 const WAVE_FREQUENCY = 0.012;

 // 每格分成幾段繪製
 // 越高越平滑，但比較吃效能
 const SEGMENTS = 2;

 // 動畫更新頻率
 const TARGET_FPS = 30;


 // ==========================================
 // 2. 確認圖層與 PixiJS
 // ==========================================

 if (
   typeof PIXI !== "undefined" &&
   typeof PIXI.Graphics === "function" &&
   runtimeScene.hasLayer(GRID_LAYER)
 ) {

   const layer = runtimeScene
     .getLayer(GRID_LAYER)
     .getRendererObject();

   if (layer) {

     const W = runtimeScene.getViewportWidth();
     const H = runtimeScene.getViewportHeight();

     let fx = runtimeScene._gridBreathFX;


     // ======================================
     // 3. 第一次建立網格
     // ======================================

     if (
       !fx ||
       fx.layer !== layer ||
       fx.width !== W ||
       fx.height !== H ||
       fx.graphics.parent !== layer
     ) {

       // 清除舊的網格
       if (fx && fx.graphics) {
         fx.graphics.destroy();
       }

       const graphics = new PIXI.Graphics();

       // 不攔截滑鼠 / 觸控
       graphics.interactive = false;

       // 放進指定圖層
       layer.addChildAt(graphics, 0);

       fx = {
         layer: layer,
         graphics: graphics,
         width: W,
         height: H,
         time: 0,
         accumulator: 0,
         firstFrame: true
       };

       runtimeScene._gridBreathFX = fx;
     }


     // ======================================
     // 4. 計算時間
     // ======================================

     const dt = Math.max(
       0,
       Math.min(
         runtimeScene.getElapsedTime() / 1000,
         0.05
       )
     );

     fx.time += dt;
     fx.accumulator += dt;


     // ======================================
     // 5. 限制重繪頻率
     // ======================================

     if (
       fx.firstFrame ||
       fx.accumulator >= 1 / TARGET_FPS
     ) {

       fx.firstFrame = false;
       fx.accumulator = 0;

       const t = fx.time;

       const g = fx.graphics;


       // ====================================
       // 6. 緩慢移動的波紋中心
       // ====================================

       const centerX =
         W * (
           0.5 +
           Math.sin(t * 0.18) * 0.18
         );

       const centerY =
         H * (
           0.5 +
           Math.cos(t * 0.15) * 0.16
         );


       // ====================================
       // 7. 整體呼吸
       // ====================================

       const breath =
         Math.sin(t * BREATH_SPEED) *
         BREATH_STRENGTH;


       // ====================================
       // 8. 網格變形函式
       //
       // 輸入原始座標
       // 回傳變形後座標
       // ====================================

       function distort(x, y) {

         const dx = x - centerX;
         const dy = y - centerY;

         const distance = Math.max(
           1,
           Math.hypot(dx, dy)
         );

         // 波紋從中心向外擴散
         const phase =
           distance * WAVE_FREQUENCY -
           t * WAVE_SPEED;

         const wave = Math.sin(phase);

         // 越遠離中心，效果越淡
         const influence = Math.exp(
           -Math.pow(
             distance / (Math.max(W, H) * 0.65),
             2
           )
         );

         // 波動 + 呼吸
         const amount =
           (
             wave * DISTORT_STRENGTH +
             breath
           ) * influence;


         // 向外 / 向內推動
         const radialX =
           (dx / distance) * amount;

         const radialY =
           (dy / distance) * amount;


         // 額外的柔和流動
         const flowX =
           Math.sin(
             y * 0.006 +
             t * 0.30
           ) * 4;

         const flowY =
           Math.cos(
             x * 0.006 -
             t * 0.25
           ) * 4;


         return {
           x: x + radialX + flowX,
           y: y + radialY + flowY
         };
       }


       // ====================================
       // 9. 清除上一幀畫面
       // ====================================

       g.clear();

       g.lineStyle(
         LINE_WIDTH,
         LINE_COLOR,
         LINE_ALPHA
       );


       // ====================================
       // 10. 畫出垂直線
       // ====================================

       const step =
         GRID_SPACING / SEGMENTS;

       const left = -GRID_SPACING;
       const right = W + GRID_SPACING;

       const top = -GRID_SPACING;
       const bottom = H + GRID_SPACING;


       for (
         let x = left;
         x <= right;
         x += GRID_SPACING
       ) {

         let first = true;

         for (
           let y = top;
           y <= bottom;
           y += step
         ) {

           const p = distort(x, y);

           if (first) {
             g.moveTo(p.x, p.y);
             first = false;
           } else {
             g.lineTo(p.x, p.y);
           }
         }
       }


       // ====================================
       // 11. 畫出水平線
       // ====================================

       for (
         let y = top;
         y <= bottom;
         y += GRID_SPACING
       ) {

         let first = true;

         for (
           let x = left;
           x <= right;
           x += step
         ) {

           const p = distort(x, y);

           if (first) {
             g.moveTo(p.x, p.y);
             first = false;
           } else {
             g.lineTo(p.x, p.y);
           }
         }
       }
     }
   }
 }

};
