"use strict";
 // ========================================
 // CHAIN / MATCH
 // 橫向／直向／十字消除光束特效
 // 不修改原本的技能與三消功能
 // ========================================

 const anim = runtimeScene._chainMatchAnimation;
 const dt = runtimeScene.getElapsedTime() / 1000;

 // 特效設定
 const DURATION = 0.32;

 // ========================================
 // 1. 偵測新的消除波次
 // ========================================

 if (
   anim &&
   anim.matched &&
   anim.board &&
   anim.matched !== anim._lineFXLastMatched
 ) {

   anim._lineFXLastMatched = anim.matched;

   const board = anim.board;
   const matched = anim.matched;

   const lines = [];

   // 取得棋盤格距
   const dx = Math.abs(
     board[1].getCenterXInScene() -
     board[0].getCenterXInScene()
   );

   const dy = Math.abs(
     board[6].getCenterYInScene() -
     board[0].getCenterYInScene()
   );

   // ====================================
   // 2. 檢查整排橫向消除
   // ====================================

   for (let row = 0; row < 6; row++) {

     const ids = [];

     for (let col = 0; col < 6; col++) {
       ids.push(row * 6 + col);
     }

     if (ids.every(id => matched.has(id))) {

       const first = board[ids[0]];
       const last = board[ids[5]];

       lines.push({
         x1: first.getCenterXInScene() - dx * 0.45,
         y1: first.getCenterYInScene(),
         x2: last.getCenterXInScene() + dx * 0.45,
         y2: last.getCenterYInScene()
       });
     }
   }

   // ====================================
   // 3. 檢查整列直向消除
   // ====================================

   for (let col = 0; col < 6; col++) {

     const ids = [];

     for (let row = 0; row < 6; row++) {
       ids.push(row * 6 + col);
     }

     if (ids.every(id => matched.has(id))) {

       const first = board[ids[0]];
       const last = board[ids[5]];

       lines.push({
         x1: first.getCenterXInScene(),
         y1: first.getCenterYInScene() - dy * 0.45,
         x2: last.getCenterXInScene(),
         y2: last.getCenterYInScene() + dy * 0.45
       });
     }
   }

   // ====================================
   // 4. 啟動光束
   // ====================================

   if (lines.length > 0) {

     runtimeScene._lineSkillAnimation = {
       lines: lines,
       time: 0,
       duration: DURATION,
       size: Math.min(dx, dy)
     };

     // 建立繪製物件，只需要建立一次
     if (!runtimeScene._lineSkillPainter) {

       const painter = runtimeScene.createObject(
         "LineSkillFX"
       );

       if (painter) {
         runtimeScene._lineSkillPainter = painter;

         painter.setCoordinatesRelative(false);
         painter.setClearBetweenFrames(true);
       }
     }

     const painter = runtimeScene._lineSkillPainter;

     if (painter) {
       painter.setLayer(board[0].getLayer());
       painter.setZOrder(
         board[0].getZOrder() + 200
       );
     }
   }
 }

 // ========================================
 // 5. 每幀更新光束動畫
 // ========================================

 const painter = runtimeScene._lineSkillPainter;
 const fx = runtimeScene._lineSkillAnimation;

 if (painter) {

   // 清除上一幀繪製的光束
   painter.clear();

   if (fx) {

     fx.time += dt;

     const p = Math.min(
       fx.time / fx.duration,
       1
     );

     // 光束快速延伸
     const progress =
       1 - Math.pow(1 - p, 3);

     // 後段逐漸淡出
     const fade = Math.min(
       1,
       (1 - p) / 0.35
     );

     for (const line of fx.lines) {

       const x2 = line.x1 +
         (line.x2 - line.x1) * progress;

       const y2 = line.y1 +
         (line.y2 - line.y1) * progress;


 // ========================================
 // 整排光束：依角色特效切換顏色
 // ========================================

 const isRockExplosion =
   runtimeScene.getGame()
     .getVariables()
     .get("SelectedCharacter")
     .getAsNumber() === 5 &&
   Array.isArray(runtimeScene._rockBlasts) &&
   runtimeScene._rockBlasts.length > 0;

 painter.setOutlineColor(
   runtimeScene._whiteUltimateFX
     ? "255;215;110"  // 白：暖金黃
     : isRockExplosion
       ? "60;90;215"  // 玫君：群青色
       : "190;160;255" // 其他：淡紫色
 );

       painter.setOutlineOpacity(110 * fade);

       painter.drawLine(
         line.x1,
         line.y1,
         x2,
         y2,
         fx.size * 0.38
       );

       // 中心白色亮光
       painter.setOutlineColor("255;255;255");
       painter.setOutlineOpacity(240 * fade);

       painter.drawLine(
         line.x1,
         line.y1,
         x2,
         y2,
         fx.size * 0.09
       );

       // 光束前端的小光點
       painter.setOutlineOpacity(0);
       painter.setFillColor("255;255;255");
       painter.setFillOpacity(220 * fade);

       painter.drawCircle(
         x2,
         y2,
         fx.size * 0.12
       );
     }

     // 時間結束，停止特效
     if (p >= 1) {
       runtimeScene._lineSkillAnimation = null;
       painter.clear();
     }
   }
 }

