gdjs._36938_25138Code.userFunc0xa0f038 = function GDJSInlineCode(runtimeScene) {
"use strict";
// ========================================
// CHAIN / COMBO 動畫：Tween 輕量版
//
// 只在數字變化時啟動動畫
// 不會每幀重新設定字體大小
// 保留原本的顯示條件和時間
//
// ChainPopup / ComboPopup
// 都需要加入 Tween 行為
// ========================================

const vars = runtimeScene.getVariables();

const chainPopup =
  runtimeScene.getObjects("ChainPopup")[0];

const comboPopup =
  runtimeScene.getObjects("ComboPopup")[0];

if (chainPopup && comboPopup) {

  const dt = runtimeScene.getElapsedTime() / 1000;

  const CHAIN_DURATION = 1.2;
  const COMBO_DURATION = 0.8;

  // ======================================
  // 1. 第一次執行：記錄原始位置
  // ======================================

  if (!runtimeScene._popupTweenUI) {

    runtimeScene._popupTweenUI = {

      chain: {
        x: chainPopup.getX(),
        y: chainPopup.getY(),
        scale: chainPopup.getScaleX(),
        active: false
      },

      combo: {
        x: comboPopup.getX(),
        y: comboPopup.getY(),
        scale: comboPopup.getScaleX(),
        active: false
      }

    };
  }

  const ui = runtimeScene._popupTweenUI;

  // ======================================
  // 2. 播放彈出動畫
  // ======================================

  function playPopup(popup, data, text, duration, floatY) {

    const tween = popup.getBehavior("Tween");

    if (!tween) return;

    // 先停止上一輪的動畫
    tween.removeTween("PopupScale");
    tween.removeTween("PopupMove");
    tween.removeTween("PopupFade");

    // 更新文字
    popup.setString(text);

    // 將文字置中於原始位置附近
    const centerX =
      data.x + popup.getWidth() / 2;

    const x = centerX - popup.getWidth() / 2;

    // 設定彈出前的起始狀態
    popup.setPosition(x, data.y + 12);

    popup.setScale(data.scale * 0.82);

    popup.setOpacity(255);
    popup.hide(false);

    // ------------------------------------
    // A. 文字快速放大回彈
    // ------------------------------------

    tween.addObjectScaleTween3(
      "PopupScale",
      data.scale,
      "easeOutBack",
      0.28,
      false,
      true
    );

    // ------------------------------------
    // B. 文字向上浮動
    // ------------------------------------

    tween.addObjectPositionYTween2(
      "PopupMove",
      data.y - floatY,
      "easeOutQuad",
      duration,
      false
    );

    // ------------------------------------
    // C. 逐漸淡出
    // ------------------------------------

    tween.addObjectOpacityTween2(
      "PopupFade",
      0,
      "easeInQuad",
      duration,
      false
    );

    data.active = true;
  }

  // ======================================
  // 3. CHAIN 觸發
  // ======================================

  const chain = vars.get("Chain").getAsNumber();

  const lastChain =
    vars.get("PopupLastChain").getAsNumber();

  if (chain >= 2 && chain !== lastChain) {

    playPopup(
      chainPopup,
      ui.chain,
      "CHAIN × " + chain,
      CHAIN_DURATION,
      5
    );

    vars.get("ChainPopupTime").setNumber(
      CHAIN_DURATION
    );
  }

  vars.get("PopupLastChain").setNumber(chain);

  // ======================================
  // 4. COMBO 觸發
  // ======================================

  const combo =
    vars.get("LastCombo").getAsNumber();

  const lastCombo =
    vars.get("PopupLastCombo").getAsNumber();

  if (combo >= 2 && combo !== lastCombo) {

    playPopup(
      comboPopup,
      ui.combo,
      "COMBO × " + combo + "!",
      COMBO_DURATION,
      30
    );

    vars.get("ComboPopupTime").setNumber(
      COMBO_DURATION
    );
  }

  vars.get("PopupLastCombo").setNumber(combo);

  // ======================================
  // 5. 原本的顯示倒數
  // ======================================

  const chainTime = Math.max(
    0,
    vars.get("ChainPopupTime").getAsNumber() - dt
  );

  const comboTime = Math.max(
    0,
    vars.get("ComboPopupTime").getAsNumber() - dt
  );

  vars.get("ChainPopupTime").setNumber(chainTime);
  vars.get("ComboPopupTime").setNumber(comboTime);

  // ======================================
  // 6. CHAIN 播放結束
  // ======================================

  if (chainTime <= 0 && ui.chain.active) {

    chainPopup.hide(true);

    chainPopup.setScale(ui.chain.scale);

    chainPopup.setPosition(
      ui.chain.x,
      ui.chain.y
    );

    ui.chain.active = false;
  }

  // ======================================
  // 7. COMBO 播放結束
  // ======================================

  if (comboTime <= 0 && ui.combo.active) {

    comboPopup.hide(true);

    comboPopup.setScale(ui.combo.scale);

    comboPopup.setPosition(
      ui.combo.x,
      ui.combo.y
    );

    ui.combo.active = false;
  }
}

};
