gdjs._36938_25138Code.userFunc0xd9cae8 = function GDJSInlineCode(runtimeScene) {
"use strict";
// ========================================
// 無效交換：棋子左右搖晃
// 純視覺效果，不修改遊戲數值
// ========================================

const shake = runtimeScene._invalidSwapShake;

if (shake) {

  const dt = runtimeScene.getElapsedTime() / 1000;

  shake.elapsed += dt;

  // 動畫進度：0 ～ 1
  const t = Math.min(
    shake.elapsed / shake.duration,
    1
  );

  // 搖晃幅度會逐漸減小
  const strength = 7 * (1 - t);

  // 左右震動，約 3 次
  const offset =
    Math.sin(t * Math.PI * 6) * strength;

  // 兩顆棋子一起搖晃
  for (let i = 0; i < shake.pieces.length; i++) {

    const piece = shake.pieces[i];

    if (piece) {
      piece.setX(
        shake.positions[i] + offset
      );
    }
  }

  // 動畫結束：恢復原位
  if (t >= 1) {

    for (let i = 0; i < shake.pieces.length; i++) {

      const piece = shake.pieces[i];

      if (piece) {
        piece.setX(shake.positions[i]);
      }
    }

    runtimeScene._invalidSwapShake = null;
  }
}

};
gdjs._36938_25138Code.userFunc0x1139550 = function GDJSInlineCode(runtimeScene) {
"use strict";
// ========================================
// Game 倒數計時器 + 角色對話觸發
//
// 保留：
// 1. 120 秒限時模式
// 2. 佐代「時間相對論」暫停時間
// 3. TIME 文字顯示
// 4. 時間結束顯示結算按鈕
//
// 新增：
// 剩 15 秒 → DialogueLowTimePulse +1
// 遊戲結束 → DialogueEndPulse +1
// ========================================

const v = runtimeScene.getVariables();

const timeText =
  runtimeScene.getObjects("TimeText")[0];

const timeUpText =
  runtimeScene.getObjects("TimeUpText")[0];

const resultButton =
  runtimeScene.getObjects("ResultButton")[0];

const mode = v.get("GameMode").getAsNumber();
const timeUp = v.get("TimeUp").getAsNumber();
const busy = v.get("Busy").getAsNumber();

const dt = runtimeScene.getElapsedTime() / 1000;

// ========================================
// 1. 限時模式倒數
// ========================================

if (mode === 1 && timeUp === 0) {

  // 佐代時間相對論：暫停倒數
  const stop = v.get("TimeStopLeft");

  const oldStop = Math.max(
    0,
    stop.getAsNumber()
  );

  const frozen = Math.min(dt, oldStop);

  stop.setNumber(
    Math.max(0, oldStop - dt)
  );

  // 計算剩餘時間
  const timeLeft = v.get("TimeLeft");

  const previousTime = timeLeft.getAsNumber();

  const remaining = Math.max(
    0,
    previousTime - (dt - frozen)
  );

  timeLeft.setNumber(remaining);

  // ======================================
  // 2. 更新 TIME 文字
  // ======================================

  const sec = Math.ceil(remaining);
  const min = Math.floor(sec / 60);
  const s = sec % 60;

  if (timeText) {

    timeText.setString(
      "TIME  " +
      String(min).padStart(2, "0") +
      ":" +
      String(s).padStart(2, "0")
    );
  }

  // ======================================
  // 3. 剩餘 15 秒：通知對話系統
  // ======================================

  // 只在倒數從 15 秒以上
  // 第一次進入 15 秒內時觸發。
  //
  // 不會每一幀重複加 1。

  if (
    previousTime > 15 &&
    remaining <= 15 &&
    remaining > 0
  ) {

    v.get("DialogueLowTimePulse").add(1);
  }

  // ======================================
  // 4. 遊戲時間結束
  // ======================================

  if (remaining <= 0 && busy === 0) {

    // 標記遊戲結束
    v.get("TimeUp").setNumber(1);

    // 告知對話系統，觸發結束台詞
    v.get("DialogueEndPulse").add(1);

    // 顯示遊戲結束 UI
    if (timeUpText) {
      timeUpText.hide(false);
    }

    if (resultButton) {
      resultButton.hide(false);
    }
  }
}

// ========================================
// 5. 自由模式隱藏計時器
// ========================================

if (mode === 2 && timeText) {
  timeText.hide(true);
}

};
