const chain =
  v.get("Chain").getAsNumber();

const combo =
  v.get("LastCombo").getAsNumber();

const fever =
  v.get("FeverActive").getAsNumber();

const skillPulse =
  v.get("DialogueSkillPulse").getAsNumber();

const endPulse =
  v.get("DialogueEndPulse").getAsNumber();

const lowTimePulse =
  v.get("DialogueLowTimePulse").getAsNumber();

// ========================================
// 9. 偵測並觸發對話
// ========================================

// 遊戲結束優先於其他對話
if (endPulse !== ui.lastEndPulse) {

  tryDialogue("end", true);

} else if (!ui.started) {

  // 進入遊戲時必定說一句
  ui.started = true;

  tryDialogue("start", true);

} else if (
  lowTimePulse !== ui.lastLowTimePulse
) {

  // 剩餘 15 秒
  tryDialogue("lowTime");

} else if (
  fever === 1 &&
  ui.lastFever === 0
) {

  // FEVER 剛啟動
  tryDialogue("fever");

} else if (
  skillPulse !== ui.lastSkillPulse
) {

  // 技能成功施放
  tryDialogue("skill");

} else if (
  combo >= 3 &&
  ui.lastCombo < 3
) {

  // COMBO 第一次達到 3
  tryDialogue("combo");

} else if (
  chain >= 5 &&
  ui.lastChain < 5
) {

  // CHAIN 第一次達到 5
  tryDialogue("chain");
}

// ========================================
// 10. 記錄這一幀的事件數值
// ========================================

ui.lastChain = chain;
ui.lastCombo = combo;
ui.lastFever = fever;

ui.lastSkillPulse = skillPulse;
ui.lastEndPulse = endPulse;
ui.lastLowTimePulse = lowTimePulse;

// ========================================
// 11. 顯示或隱藏對話框
// ========================================

const visible = ui.remaining > 0;

if (bg) {
  bg.hide(!visible);
}

if (nameBG) {
  nameBG.hide(!visible);
}

if (nameText) {
  nameText.hide(!visible);
}

if (dialogueText) {
  dialogueText.hide(!visible);
}

// ========================================
// 12. 更新名字與台詞
// ========================================

if (visible && data) {

  if (nameText) {
    nameText.setString(data.name);
  }

  if (dialogueText) {
    dialogueText.setString(ui.currentText);
  }
}

