"use strict";
const vars = runtimeScene.getVariables();

// 玩家目前的 EP
const ep = vars.get("EP").getAsNumber();

// 三個技能按鈕
const skills = [
  { name: "Skill1Button", cost: 20 },
  { name: "Skill2Button", cost: 40 },
  { name: "Skill3Button", cost: 80 }
];

// 根據 EP 決定按鈕亮度
for (const skill of skills) {

  const button = runtimeScene.getObjects(skill.name)[0];

  if (!button) continue;

  if (ep >= skill.cost) {
    // EP 足夠：正常顯示
    button.setOpacity(255);
  } else {
    // EP 不足：變暗
    button.setOpacity(90);
  }
}

