    ["屬於我們的搖滾演唱會", "將場上部分顏色的棋子轉為炸彈，\n並立即引爆。"],
    ["搖滾吉他", "每累積引爆 3 顆炸彈，\n獲得額外炸彈生成獎勵。"]
