gdjs._36938_25138Code.userFunc0xdde458 = function GDJSInlineCode(runtimeScene) {
"use strict";
// ========================================
// 指定型技能：棋子 Hover 白框
// 純 UI，不影響技能、EP、FEVER
// ========================================

const v = runtimeScene.getVariables();

const skillMode = v.get("SkillMode").getAsNumber();
const busy = v.get("Busy").getAsNumber();
const timeUp = v.get("TimeUp").getAsNumber();

const frame = runtimeScene
  .getObjects("TargetHoverFrame")[0];

if (frame) {

  // 預設隱藏外框
  frame.hide(true);

  // 只有等待選擇目標時才啟用
  if (
    skillMode === 1 &&
    busy === 0 &&
    timeUp === 0
  ) {

    const mouseX = gdjs.evtTools.input.getCursorX(
      runtimeScene, "", 0
    );

    const mouseY = gdjs.evtTools.input.getCursorY(
      runtimeScene, "", 0
    );

    const pieces = runtimeScene.getObjects("NewSprite");

    // 尋找滑鼠目前指向的棋子
    for (const piece of pieces) {

      const x = piece.getX();
      const y = piece.getY();
      const width = piece.getWidth();
      const height = piece.getHeight();

      if (
        mouseX >= x &&
        mouseX <= x + width &&
        mouseY >= y &&
        mouseY <= y + height
      ) {

        // 外框對齊棋子
        frame.setPosition(x, y);
        frame.setWidth(width);
        frame.setHeight(height);

        // 顯示在棋子上方
        frame.setZOrder(piece.getZOrder() + 10);

        frame.hide(false);
        break;
      }
    }
  }
}

};
