  1:{1:'shuffle',2:'sudoku',3:'sunshine'},
  2:{1:'helpRecolor',2:'chainGuard',3:'support'},
  3:{1:'deduction',2:'guardianStone',3:'timeStop'},
  4:{1:'demonCross',2:'demonTriple',3:'demonClearAll'},
  5:{1:'rockBomb1',2:'rockBomb3',3:'rockConcert'},
  6:{1:'blackHint',2:'blackWildOne',3:'blackWildFive'}
