gdjs._36938_25138Code.userFunc0xf6f4b0 = function GDJSInlineCode(runtimeScene) {
"use strict";
 // ==========================================
 // CHAIN / MATCH
 // 黑子：萬用棋子生成特效 V1
 //
 // 黑白雜訊 + 方框閃現 + 像素碎片
 //
 // 自動偵測新增的萬用棋子
 // 動畫編號 6 = 萬用棋子
 //
 // 不修改技能、棋子、EP 或消除
 // ==========================================

 const ch = runtimeScene.getGame()
   .getVariables()
   .get("SelectedCharacter")
   .getAsNumber();

 const dt = Math.min(
   runtimeScene.getElapsedTime() / 1000,
   0.05
 );

 const DURATION = 0.42;

 // ==========================================
 // 1. 取得棋盤
 // ==========================================

 const board = Array(36).fill(null);

 for (
   const piece of runtimeScene.getObjects(
     "NewSprite"
   )
 ) {

   const id = piece.getVariables()
     .get("ID")
     .getAsNumber();

   if (id >= 0 && id < 36) {
     board[id] = piece;
   }
 }

 // 取得目前每格的動畫編號
 const current = board.map(
   piece =>
     piece ? piece.getAnimationIndex() : -1
 );

 // ==========================================
 // 2. 初始化紀錄
 // ==========================================

 if (
   !Array.isArray(runtimeScene._blackWildPrevious)
 ) {

   runtimeScene._blackWildPrevious =
     current.slice();

 }

 if (!Array.isArray(runtimeScene._blackWildFX)) {

   runtimeScene._blackWildFX = [];
 }

 // ==========================================
 // 3. 偵測新生成的萬用棋子
 // ==========================================

 if (
   ch === 6 &&
   board.every(Boolean)
 ) {

   const previous =
     runtimeScene._blackWildPrevious;

   const oldCount = previous.filter(
     value => value === 6
   ).length;

   const newCount = current.filter(
     value => value === 6
   ).length;

   // 只有場上萬用棋子總數增加，
   // 才判定為新生成
   // 避免普通交換也重複播放
   if (newCount > oldCount) {

     for (let id = 0; id < 36; id++) {

       if (
         current[id] !== 6 ||
         previous[id] === 6
       ) {
         continue;
       }

       const piece = board[id];

       runtimeScene._blackWildFX.push({

         x: piece.getCenterXInScene(),
         y: piece.getCenterYInScene(),

         size: Math.min(
           piece.getWidth(),
           piece.getHeight()
         ),

         layer: piece.getLayer(),
         z: piece.getZOrder() + 260,

         time: 0,
         duration: DURATION,

         // 每顆棋子的小雜訊不同
         seed: Math.random() * 1000
       });
     }
   }
 }

 // 每幀更新記錄
 runtimeScene._blackWildPrevious =
   current.slice();

 // ==========================================
 // 4. 建立特效繪製器
 // ==========================================

 let painter =
   runtimeScene._blackWildPainter;

 if (
   runtimeScene._blackWildFX.length > 0 &&
   !painter
 ) {

   painter = runtimeScene.createObject(
     "BlackWildSpawnFX"
   );

   if (painter) {

     runtimeScene._blackWildPainter = painter;

     painter.setCoordinatesRelative(false);
     painter.setClearBetweenFrames(true);
   }
 }

 // ==========================================
 // 5. 更新生成動畫
 // ==========================================

 if (painter) {

   painter.clear();

   const active = [];

   for (
     const fx of runtimeScene._blackWildFX
   ) {

     fx.time += dt;

     const p = Math.min(
       fx.time / fx.duration,
       1
     );

     if (p >= 1) continue;

     active.push(fx);

     painter.setLayer(fx.layer);
     painter.setZOrder(fx.z);

     const x = fx.x;
     const y = fx.y;
     const size = fx.size;

     const fade = Math.max(0, 1 - p);

     // ====================================
     // A. 白色瞬間閃光
     // ====================================

     const flash = p < 0.12
       ? p / 0.12
       : Math.max(
           0,
           1 - (p - 0.12) / 0.35
         );

     painter.setOutlineOpacity(0);

     painter.setFillColor("255;255;255");
     painter.setFillOpacity(
       130 * flash
     );

     painter.drawRectangle(
       x - size * 0.38,
       y - size * 0.38,
       x + size * 0.38,
       y + size * 0.38
     );

     // ====================================
     // B. 黑白生成方框
     // ====================================

     const scale =
       0.25 + Math.min(p / 0.5, 1) * 0.32;

     const half = size * scale;

     // 外層黑色粗框
     painter.setFillOpacity(0);

     painter.setOutlineColor("20;20;28");
     painter.setOutlineOpacity(
       220 * fade
     );

     painter.setOutlineSize(8);

     painter.drawRectangle(
       x - half,
       y - half,
       x + half,
       y + half
     );

     // 內層白色細框
     painter.setOutlineColor("255;255;255");
     painter.setOutlineOpacity(
       245 * fade
     );

     painter.setOutlineSize(3);

     painter.drawRectangle(
       x - half,
       y - half,
       x + half,
       y + half
     );

     // ====================================
     // C. 黑白雜訊橫線
     // ====================================

     const glitch =
       p < 0.45 ? 1 : 0;

     if (glitch > 0) {

       const jitter =
         Math.sin(
           fx.seed + fx.time * 110
         ) * size * 0.055;

       const lines = [
         [-0.26, -0.36, 0.12],
         [0.08, -0.12, 0.44],
         [-0.32, 0.19, 0.17]
       ];

       for (let i = 0; i < lines.length; i++) {

         const data = lines[i];

         const sx =
           x + size * data[0] + jitter;

         const sy =
           y + size * data[1];

         const ex =
           x + size * data[2] + jitter;

         painter.setOutlineOpacity(0);

         painter.setFillColor(
           i % 2 === 0
             ? "255;255;255"
             : "45;45;55"
         );

         painter.setFillOpacity(
           210 * fade
         );

         painter.drawRectangle(
           sx,
           sy,
           ex,
           sy + size * 0.045
         );
       }
     }

     // ====================================
     // D. 四角像素碎片
     // ====================================

     const distance =
       size * (0.18 + p * 0.65);

     const pixels = [
       [-1, -1],
       [1, -1],
       [-1, 1],
       [1, 1]
     ];

     for (let i = 0; i < pixels.length; i++) {

       const px =
         x + pixels[i][0] * distance;

       const py =
         y + pixels[i][1] * distance;

       const pixelSize =
         Math.max(
           1,
           size * 0.075 * fade
         );

       painter.setOutlineOpacity(0);

       painter.setFillColor(
         i % 2 === 0
           ? "255;255;255"
           : "155;155;170"
       );

       painter.setFillOpacity(
         220 * fade
       );

       painter.drawRectangle(
         px - pixelSize / 2,
         py - pixelSize / 2,
         px + pixelSize / 2,
         py + pixelSize / 2
       );
     }

     // ====================================
     // E. 中央小十字閃光
     // ====================================

     if (p < 0.45) {

       const alpha =
         220 * (1 - p / 0.45);

       const reach =
         size * (0.10 + p * 0.24);

       painter.setFillOpacity(0);
       painter.setOutlineColor("255;255;255");
       painter.setOutlineOpacity(alpha);

       painter.drawLine(
         x - reach, y,
         x + reach, y,
         3
       );

       painter.drawLine(
         x, y - reach,
         x, y + reach,
         3
       );
     }
   }

   // 移除已播放完的特效
   runtimeScene._blackWildFX = active;
 }

};
