gdjs._36938_25138Code.userFunc0x156fce8 = function GDJSInlineCode(runtimeScene) {
"use strict";
const vars = runtimeScene.getVariables();

const success = vars.get("SkillSuccess").getAsNumber();

if (success === 1) {

  const skill = vars.get("SelectedSkill").getAsNumber();

  // 各技能的 EP 消耗
  const costs = {
    1: 20,
    2: 40,
    3: 80
  };

  const cost = costs[skill];

  // 技能成功才扣除 EP
  if (cost !== undefined) {

    const ep = vars.get("EP");

    ep.setNumber(
      Math.max(0, ep.getAsNumber() - cost)
    );
  }

  // =====================================
  // 清除技能選擇狀態
  // =====================================

  vars.get("SelectedSkill").setNumber(0);
  vars.get("LastSelectedSkill").setNumber(0);

  // 清除上一招的效果名稱
  vars.get("SkillEffect").setString("");

  // 恢復普通交換模式
  vars.get("SkillMode").setNumber(0);
  vars.get("SkillTarget").setNumber(-1);

  // 清除技能執行紀錄
  vars.get("SkillExecuting").setNumber(0);
  vars.get("SkillSuccess").setNumber(0);

  // =====================================
  // 清除普通棋盤選取狀態
  // =====================================

  vars.get("ClickStep").setNumber(0);
  vars.get("FirstID").setNumber(-1);
  vars.get("SecondID").setNumber(-1);
  vars.get("SelectedID").setNumber(-1);
  vars.get("CanSwap").setNumber(0);
}

};
gdjs._36938_25138Code.userFunc0xfa7788 = function GDJSInlineCode(runtimeScene) {
"use strict";
// 指定型技能操作提示（完整修正版）
// 白底黑框 Sprite + 自動換行文字
// 六位角色共用
// 不修改 EP 或技能施放
// ========================================

// ========================================
// 1. 取得場景變數
// ========================================

const hintVars = runtimeScene.getVariables();

const hintCharacter = runtimeScene
  .getGame()
  .getVariables()
  .get("SelectedCharacter")
  .getAsNumber();

const hintSkill = hintVars
  .get("SelectedSkill")
  .getAsNumber();

const hintMode = hintVars
  .get("SkillMode")
  .getAsNumber();

const hintBusy = hintVars
  .get("Busy")
  .getAsNumber();

const hintTimeUp = hintVars
  .get("TimeUp")
  .getAsNumber();

// ========================================
// 2. 取得提示框物件
// ========================================

// 白底黑框背景：Sprite
const hintBG = runtimeScene
  .getObjects("TargetSkillHintBG")[0];

// 黑色提示文字：普通文字物件
const hintText = runtimeScene
  .getObjects("TargetSkillHintText")[0];

// ========================================
// 3. 提示框設定
// ========================================

// 背景大小
const BOX_WIDTH = 380;
const BOX_HEIGHT = 52;

// 畫面位置
const BOX_X = 1190;
const BOX_Y = 24;

// 文字左右留白
const PADDING = 20;

// 文字大小
const FONT_SIZE = 26;

// 可用文字寬度
const TEXT_WIDTH = BOX_WIDTH - PADDING * 2;

// ========================================
// 4. 五個指定型技能的提示
// ========================================

const hintMessages = {

  // 史威特：技能 2
  1: {
    2: "請選擇要重新排列的棋子"
  },

  // 沏萊爾：技能 1
  2: {
    1: "請選擇要改變顏色的棋子"
  },

  // 佐代：技能 1
  3: {
    1: "請選擇要進行推理的棋子"
  },

  // 白：技能 1、技能 2
  4: {
    1: "請選擇十字消除的中心棋子",
    2: "請選擇要製造三連的位置"
  },

  // 玫君、黑子沒有指定型技能
  5: {},
  6: {}
};

// ========================================
// 5. 判斷是否正在指定技能
// ========================================

const characterHints =
  hintMessages[hintCharacter] || {};

const message =
  characterHints[hintSkill] || "";

// 只有等待玩家選棋子時顯示
const waiting =
  message !== "" &&
  hintMode === 1 &&
  hintBusy === 0 &&
  hintTimeUp === 0;

// ========================================
// 6. 顯示 / 隱藏提示框
// ========================================

if (hintBG && hintText) {

  if (waiting) {

    // ------------------------------------
    // A. 白底黑框背景
    // ------------------------------------

    hintBG.setPosition(BOX_X, BOX_Y);

    hintBG.setWidth(BOX_WIDTH);
    hintBG.setHeight(BOX_HEIGHT);

    hintBG.setZOrder(850);

    // ------------------------------------
    // B. 更新文字
    // ------------------------------------

    hintText.setString(message);

    // 設定文字大小
    if (
      typeof hintText.setCharacterSize === "function"
    ) {
      hintText.setCharacterSize(FONT_SIZE);
    }

    // 開啟自動換行
    if (
      typeof hintText.setWrapping === "function"
    ) {
      hintText.setWrapping(true);
    }

    // 限制文字最大寬度
    if (
      typeof hintText.setWrappingWidth === "function"
    ) {
      hintText.setWrappingWidth(TEXT_WIDTH);
    }

    // 水平置中
    if (
      typeof hintText.setTextAlignment === "function"
    ) {
      hintText.setTextAlignment("center");
    }

    // 設為黑字
    if (
      typeof hintText.setColor === "function"
    ) {
      hintText.setColor("255;255;255");
    }

    // ------------------------------------
    // C. 文字位置
    // ------------------------------------

    // 固定文字區域左側
    const textX = BOX_X + PADDING;

    // 垂直置中
    const textY = BOX_Y + Math.max(
      0,
      (BOX_HEIGHT - hintText.getHeight()) / 2
    );

    hintText.setPosition(textX, textY);
    hintText.setZOrder(851);

    // ------------------------------------
    // D. 顯示
    // ------------------------------------

    hintBG.hide(false);
    hintText.hide(false);

  } else {

    // 技能完成、取消、遊戲結束
    hintBG.hide(true);
    hintText.hide(true);
  }
}
};
gdjs._36938_25138Code.userFunc0x1640590 = function GDJSInlineCode(runtimeScene) {
"use strict";
// ========================================
// 技能 Hover 說明系統（完整新版）
// 六位角色：3 主動技能 + 1 被動技能
// 提示框 460 × 160 px
// Padding 24 px / 說明 16 px / EP 靠右
// 不修改技能施放、EP 或遮罩
// ========================================

// ========================================
// 1. 取得角色與物件
// ========================================

const character = runtimeScene
  .getGame()
  .getVariables()
  .get("SelectedCharacter")
  .getAsNumber();

const tooltipBG =
  runtimeScene.getObjects("SkillTooltipBG")[0];

const tooltipTitle =
  runtimeScene.getObjects("SkillTooltipTitle")[0];

const tooltipCost =
  runtimeScene.getObjects("SkillTooltipCost")[0];

const tooltipDivider =
  runtimeScene.getObjects("SkillTooltipDivider")[0];

const tooltipText =
  runtimeScene.getObjects("SkillTooltipText")[0];

// 3 個主動技能 + 1 個被動技能
const buttons = [
  "Skill1Button",
  "Skill2Button",
  "Skill3Button",
  "PassiveButton"
];


// ========================================
// 2. 提示框尺寸與排版設定
// ========================================

const BOX_WIDTH = 460;
const BOX_HEIGHT = 160;

// 左右留白 24 px
const PADDING = 24;
const TEXT_WIDTH = BOX_WIDTH - PADDING * 2;

// 標題：往下移，增加上方留白
const TITLE_X = 24;
const TITLE_Y = 30;

// EP / 被動標籤：與標題對齊
const COST_RIGHT = BOX_WIDTH - PADDING;
const COST_Y = 32;

// 分隔線：往下移
const DIVIDER_X = 24;
const DIVIDER_Y = 68;

// 技能說明
const DESC_X = 24;
const DESC_Y = 80;

// ========================================
// 3. 六位角色的技能說明
// ========================================

const skillInfo = {

  // 1. 史威特
  1: [
    {
      name: "再來一次！",
      cost: 20,
      desc: "重新排列棋盤，尋找新的消除機會。"
    },
    {
      name: "來場數獨！！",
      cost: 40,
      desc: "重新排列局部 3×3 棋盤，製造消除機會。"
    },
    {
      name: "陽光一樣的心情",
      cost: 80,
      desc: "消除 12 顆棋子。接下來 5 次成功交換，強化 CHAIN、EP 與 FEVER。"
    },
    {
      name: "樂觀",
      passive: true,
      desc: "獲得 EP 與 FEVER 時，額外增加 20%。"
    }
  ],

  // 2. 沏萊爾
  2: [
    {
      name: "就…幫你一次。",
      cost: 20,
      desc: "指定一顆棋子，改變顏色以形成三連，並追加消除附近的棋子。"
    },
    {
      name: "下不為例。",
      cost: 40,
      desc: "消除一排棋子，並獲得 CHAIN 保護次數。"
    },
    {
      name: "有我在。",
      cost: 80,
      desc: "消除中央範圍棋子，增加 FEVER。接下來 5 次成功交換獲得輔助增益。"
    },
    {
      name: "穩定",
      passive: true,
      desc: "每成功交換 2 次，獲得 1 次 CHAIN 保護。交換失敗時，可消耗保護次數避免 CHAIN 歸零。"
    }
  ],

  // 3. 佐代
  3: [
    {
      name: "推理成功",
      cost: 20,
      desc: "指定棋子，重新安排附近棋盤，製造三連並追加消除。"
    },
    {
      name: "守護石的力量",
      cost: 40,
      desc: "接下來 3 次成功交換，追加消除附近棋子並強化 CHAIN。"
    },
    {
      name: "時間相對論",
      cost: 80,
      desc: "限時模式中暫停倒數 15 秒，期間獲得分數加成。"
    },
    {
      name: "擅長觀察",
      passive: true,
      desc: "每成功交換 3 次，獲得 1 層觀察。最多累積 3 層，可用來強化部分技能。"
    }
  ],

  // 4. 白
  4: [
    {
      name: "惡魔力量",
      cost: 20,
      desc: "指定棋子，消除所在的整排與整列。累積魔力後可擴大消除範圍。"
    },
    {
      name: "小作弊",
      cost: 40,
      desc: "指定位置，製造多組三連。滿層魔力時效果更強。"
    },
    {
      name: "解除封印",
      cost: 80,
      desc: "消除整個棋盤的棋子。滿層魔力時獲得額外效果。"
    },
    {
      name: "遠古的惡魔",
      passive: true,
      desc: "每次成功交換累積 1 層惡魔魔力。最多 5 層，可用來強化主動技能。"
    }
  ],

  // 5. 玫君
  5: [
    {
      name: "來者不善",
      cost: 20,
      desc: "隨機生成 1 顆炸彈棋子。交換炸彈即可引爆米字範圍。"
    },
    {
      name: "你惹到我了",
      cost: 40,
      desc: "隨機生成 3 顆炸彈棋子。炸彈之間可以連鎖引爆。"
    },
    {
      name: "屬於我們的搖滾演唱會",
      cost: 80,
      desc: "將場上指定顏色的棋子轉為炸彈，立即引爆，造成大範圍消除。"
    },
    {
      name: "搖滾吉他",
      passive: true,
      desc: "每累積引爆 3 顆炸彈，獲得額外生成 1 顆炸彈的獎勵。"
    }
  ],

  // 6. 黑子
  6: [
    {
      name: "向姊姊的求助",
      cost: 20,
      desc: "提示一組可以形成三連的交換位置。提示持續 5 秒。"
    },
    {
      name: "我的棋子",
      cost: 40,
      desc: "隨機生成最多 4 顆萬用棋子。場上最多同時存在 8 顆。"
    },
    {
      name: "讓我...讓我也派上用場吧",
      cost: 80,
      desc: "補足場上最多 8 顆萬用棋子，立即觸發三連。接下來 3 次成功交換獲得得分增益。"
    },
    {
      name: "靈活雙手",
      passive: true,
      desc: "交換時 25% 機率 CHAIN +1；萬用棋子必定 CHAIN +1、EP +5。"
    }
  ]
};

// ========================================
// 4. 顯示 / 隱藏提示框
// ========================================

const tooltipObjects = [
  tooltipBG,
  tooltipTitle,
  tooltipCost,
  tooltipDivider,
  tooltipText
];

function showTooltip(visible) {

  for (const obj of tooltipObjects) {

    if (obj) {
      obj.hide(!visible);
    }
  }
}

// ========================================
// 5. 文字設定
// ========================================

// 更新文字內容
function setText(obj, value) {

  if (!obj) return;

  if (typeof obj.setString === "function") {
    obj.setString(value);
  } else if (typeof obj.setText === "function") {
    obj.setText(value);
  }
}

// 設定字體大小
function setFontSize(obj, size) {

  if (!obj) return;

  if (typeof obj.setCharacterSize === "function") {
    obj.setCharacterSize(size);
  }
}

// 啟用自動換行
function setWrapping(obj, width) {

  if (!obj) return;

  if (typeof obj.setWrapping === "function") {
    obj.setWrapping(true);
  }

  if (typeof obj.setWrappingWidth === "function") {
    obj.setWrappingWidth(width);
  }

  if (typeof obj.setTextAlignment === "function") {
    obj.setTextAlignment("left");
  }
}

// 技能名稱：22 px
setFontSize(tooltipTitle, 26);
setWrapping(tooltipTitle, 310);

// EP / 被動標籤：18 px
setFontSize(tooltipCost, 21);

// 說明文字：14 px
setFontSize(tooltipText, 20);
setWrapping(tooltipText, TEXT_WIDTH);

// ========================================
// 6. 偵測滑鼠 Hover
// ========================================

let hoveredSkill = -1;
let hoveredButton = null;

const mouseX = gdjs.evtTools.input.getCursorX(
  runtimeScene, "", 0
);

const mouseY = gdjs.evtTools.input.getCursorY(
  runtimeScene, "", 0
);

for (let i = 0; i < buttons.length; i++) {

  const button =
    runtimeScene.getObjects(buttons[i])[0];

  if (!button) continue;

  const bounds = button.getAABB();

  const inside =
    mouseX >= bounds.min[0] &&
    mouseX <= bounds.max[0] &&
    mouseY >= bounds.min[1] &&
    mouseY <= bounds.max[1];

  if (inside) {

    hoveredSkill = i;
    hoveredButton = button;

    break;
  }
}

// ========================================
// 7. 顯示 Hover 說明
// ========================================

const info = skillInfo[character];

if (
  tooltipBG &&
  tooltipTitle &&
  tooltipCost &&
  tooltipText &&
  hoveredSkill >= 0 &&
  hoveredButton &&
  info &&
  info[hoveredSkill]
) {

  const skill = info[hoveredSkill];

  const isPassive =
    hoveredSkill === 3 ||
    skill.passive === true;

  // --------------------------------------
  // A. 更新內容
  // --------------------------------------

  // 黑子技能 3 名稱較長，縮小字體
  const titleSize =
    character === 6 && hoveredSkill === 2
      ? 21
      : 22;

  setFontSize(tooltipTitle, titleSize);

  setText(tooltipTitle, skill.name);

  setText(
    tooltipCost,
    isPassive
      ? "被動技能"
      : skill.cost + " EP"
  );

  setText(tooltipText, skill.desc);

  // --------------------------------------
  // B. 計算提示框位置
  // --------------------------------------

  let x =
    hoveredButton.getAABBCenterX()
    - BOX_WIDTH / 2;

  let y =
    hoveredButton.getAABBTop()
    - BOX_HEIGHT - 15;

  // 避免超出遊戲畫面
  x = Math.max(
    10,
    Math.min(1920 - BOX_WIDTH - 10, x)
  );

  y = Math.max(
    10,
    Math.min(1080 - BOX_HEIGHT - 10, y)
  );

  // --------------------------------------
  // C. 背景
  // --------------------------------------

  tooltipBG.setPosition(x, y);
  tooltipBG.setZOrder(900);

  // 背景自動縮放為 460 × 160
  if (
    tooltipBG.getWidth() > 0 &&
    tooltipBG.getHeight() > 0
  ) {
    tooltipBG.setWidth(BOX_WIDTH);
    tooltipBG.setHeight(BOX_HEIGHT);
  }

  // --------------------------------------
  // D. 左上：技能名稱
  // --------------------------------------

  tooltipTitle.setPosition(
    x + TITLE_X,
    y + TITLE_Y
  );

  tooltipTitle.setZOrder(902);

  // --------------------------------------
  // E. 右上：EP / 被動標籤
  // --------------------------------------

  // 用實際文字寬度靠右對齊
  const costWidth = tooltipCost.getWidth();

  tooltipCost.setPosition(
    x + COST_RIGHT - costWidth,
    y + COST_Y
  );

  tooltipCost.setZOrder(902);

  // --------------------------------------
  // F. 中間：分隔線
  // --------------------------------------

  if (tooltipDivider) {

    tooltipDivider.setPosition(
      x + DIVIDER_X,
      y + DIVIDER_Y
    );

    tooltipDivider.setWidth(TEXT_WIDTH);
    tooltipDivider.setHeight(2);

    tooltipDivider.setZOrder(901);
  }

  // --------------------------------------
  // G. 下方：技能說明
  // --------------------------------------

  tooltipText.setPosition(
    x + DESC_X,
    y + DESC_Y
  );

  tooltipText.setZOrder(902);

  // 顯示提示框
  showTooltip(true);

} else {

  // 滑鼠離開後隱藏
  showTooltip(false);
}

};
